import { Suspense } from 'react';
import { ShellHeader } from '@/components/ShellHeader';
import { GodownMetricsSkeleton } from '@/components/skeletons/GodownMetricsSkeleton';
import { RealtimeStockTicker } from '@/components/RealtimeStockTicker';
import { WarehouseAllocationGrid } from '@/components/WarehouseAllocationGrid';

// PPR flag activated at the segment level
export const experimental_ppr = true;

export default function WarehouseDashboardPage() {
  return (
    <main className="min-h-screen bg-slate-950 p-6 text-slate-100">
      {/* Static Shell: Pre-rendered at build time, delivered sub-30ms via edge */}
      <ShellHeader 
        title="Multi-Godown Stock Control"
        description="Real-time FEFO batch allocations and inventory movement."
      />

      {/* Dynamic Slot 1: Streams real-time warehouse count and low-stock telemetry */}
      <section className="my-8">
        <Suspense fallback={<GodownMetricsSkeleton />}>
          <RealtimeStockTicker />
        </Suspense>
      </section>

      {/* Dynamic Slot 2: Renders authenticated user permissions and location routing */}
      <section>
        <Suspense fallback={<div className="h-96 animate-pulse rounded-lg bg-slate-900" />}>
          <WarehouseAllocationGrid />
        </Suspense>
      </section>
    </main>
  );
}

import { cookies } from 'next/headers';
import { db } from '@/lib/database';

export async function RealtimeStockTicker() {
  // Dynamic runtime reads: Isolated inside Suspense
  const cookieStore = await cookies();
  const activeWarehouseId = cookieStore.get('active_warehouse_id')?.value ?? 'central-hub';

  // Database query triggered on request, streamed directly to edge shell
  const inventorySummary = await db.stock.aggregate({
    where: { godownId: activeWarehouseId },
    _sum: { currentQuantity: true },
    _count: { expiringBatches: true }
  });

  return (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
      <div className="p-5 rounded-xl border border-slate-800 bg-slate-900/60">
        <span className="text-xs font-mono uppercase text-emerald-400">In-Stock Units</span>
        <p className="text-3xl font-bold tracking-tight text-white mt-1">
          {inventorySummary._sum.currentQuantity?.toLocaleString() ?? 0}
        </p>
      </div>
      <div className="p-5 rounded-xl border border-slate-800 bg-slate-900/60">
        <span className="text-xs font-mono uppercase text-amber-400">FEFO Expiry Warnings</span>
        <p className="text-3xl font-bold tracking-tight text-white mt-1">
          {inventorySummary._count.expiringBatches}
        </p>
      </div>
    </div>
  );
}
